mapper.select:
SELECT id, timestamp, action, description, username, ip_address AS ipAddress,
       user_agent AS userAgent, http_method AS httpMethod, request_path AS requestPath,
       parameters, result, status, error_message AS errorMessage, class_name AS className,
       method_name AS methodName, duration_ms AS durationMs
FROM audit_logs

    AND action = #{action}
    AND username LIKE CONCAT('%', REPLACE(REPLACE(#{username}, '%', '\\%'), '_', '\\_'), '%') ESCAPE '\\'
    AND timestamp >= #{startDate}
    AND timestamp <= #{endDate}
    AND status = #{status}

ORDER BY timestamp DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM audit_logs

    AND action = #{action}
    AND username LIKE CONCAT('%', REPLACE(REPLACE(#{username}, '%', '\\%'), '_', '\\_'), '%') ESCAPE '\\'
    AND timestamp >= #{startDate}
    AND timestamp <= #{endDate}
    AND status = #{status}
